-- suite test: t_mp (auto-generated by hand, shared boilerplate)
local frame = 0
local t = 0
local function inject(keys)
  for i = 1, #keys do
    emu.write16(0x7E0700 + t, 0x1000 + keys:byte(i), emu.memType.snesMemory)
    t = (t + 2) % 64
  end
  emu.write16(0x7E00D8, t, emu.memType.snesMemory)
end
local function bufhas(str)
  for r = 0, 24 do
    local s = ""
    for c = 0, 79 do
      local ch = emu.read(0x7FE000 + r*160 + c*2, emu.memType.snesMemory)
      if ch < 32 or ch > 126 then ch = 32 end
      s = s .. string.char(ch)
    end
    if s:find(str, 1, true) then return true end
  end
  return false
end
local function bufbyte2(b1, b2)
  for r = 0, 24 do
    for c = 0, 78 do
      if emu.read(0x7FE000 + r*160 + c*2, emu.memType.snesMemory) == b1 and
         emu.read(0x7FE000 + r*160 + (c+1)*2, emu.memType.snesMemory) == b2 then
        return true
      end
    end
  end
  return false
end
local function booted()
  return bufhas("C:\\>")
end

emu.addEventCallback(function()
  frame = frame + 1
  if frame == 1200 then inject("mp\r") end
  if frame > 1200 and frame % 20 == 0 and bufhas("Multiplan:") then
    print("RESULT PASS t_mp"); emu.stop(0)
  end
  if frame == 7000 then print("RESULT FAIL t_mp"); emu.stop(0) end
end, emu.eventType.endFrame)
